function setLang(l){
  localStorage.setItem('ptaLang',l);
  document.documentElement.lang=l;
  document.querySelectorAll('[data-i18n]').forEach(e=>{
    const k=e.getAttribute('data-i18n');
    if(T[l][k])e.textContent=T[l][k];
  });
  document.getElementById('btn-es').classList.toggle('active',l==='es');
  document.getElementById('btn-en').classList.toggle('active',l==='en');
}
const sl=localStorage.getItem('ptaLang')||'es';
if(sl!=='es')setLang(sl);
function revealFooterContact(ev){
  ev.preventDefault();
  document.getElementById('footer-gate-btn').style.display='none';
  document.getElementById('footer-email').style.display='block';
  document.getElementById('footer-phone').style.display='block';
}
const hdr=document.getElementById('site-header');
window.addEventListener('scroll',()=>{hdr.classList.toggle('scrolled',window.scrollY>10);},{passive:true});
const brg=document.getElementById('burger'),mm=document.getElementById('mobile-menu');
brg.addEventListener('click',()=>{const o=brg.classList.toggle('open');brg.setAttribute('aria-expanded',o);mm.classList.toggle('open',o);});
mm.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{brg.classList.remove('open');mm.classList.remove('open');brg.setAttribute('aria-expanded','false');}));
const ro=new IntersectionObserver((es)=>{es.forEach((e,i)=>{if(e.isIntersecting){setTimeout(()=>e.target.classList.add('visible'),i*90);ro.unobserve(e.target);}});},{threshold:0.1});
document.querySelectorAll('.reveal').forEach(el=>ro.observe(el));
</script>
